def comprehension_drills():
    evens_squared = [x * x for x in range(10) if x % 2 == 0]
    word_lengths = {w: len(w) for w in ["hi", "hello", "hey"]}
    flattened = [x for row in [[1, 2], [3], [4, 5]] for x in row]
    return evens_squared, word_lengths, flattened

import itertools


def fib():
    a, b = 0, 1
    while True:
        yield a
        a, b = b, a + b


def first_n_fibs(n):
    return list(itertools.islice(fib(), n))

